// Some portions generated by Codex
package org.eclipse.rdf4j.sail.nativerdf.datastore;

import static org.assertj.core.api.Assertions.assertThat;

import java.lang.ref.Reference;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Arrays;
import java.util.HexFormat;
import java.util.concurrent.TimeUnit;
import java.util.zip.CRC32;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class DataStoreCandidateMemoryTest {

	@TempDir
	Path directory;

	@Test
	void findsLargeExistingValueWithoutCopyingCandidatePayload() throws Exception {
		Path values = Files.createDirectory(directory.resolve("values"));
		try (DataStore store = new DataStore(values.toFile(), "values", false)) {
			byte[] data = new byte[24 * 1024 * 1024];
			Arrays.fill(data, (byte) 'x');
			assertThat(store.storeData(data)).isEqualTo(1);
		}
		String classpath = System.getProperty("surefire.test.class.path", System.getProperty("java.class.path"));
		Path log = directory.resolve("candidate-memory.log");
		Process process = new ProcessBuilder(Path.of(System.getProperty("java.home"), "bin", "java").toString(),
				"-Xmx64m", "-XX:+ExitOnOutOfMemoryError", "-D" + DataFile.LARGE_READ_THRESHOLD_PROPERTY + "=67108864",
				"-cp", classpath, DataStoreCandidateMemoryTest.class.getName(), values.toString())
						.redirectErrorStream(true)
						.redirectOutput(log.toFile())
						.start();
		try {
			assertThat(process.waitFor(60, TimeUnit.SECONDS)).as("Candidate comparison probe must finish").isTrue();
			assertThat(process.exitValue()).withFailMessage("Candidate memory probe failed:%n%s", Files.readString(log))
					.isZero();
		} finally {
			process.destroyForcibly();
		}
	}

	@Test
	void distinguishesHashCollisionsBeyondTheFirstComparisonChunk() throws Exception {
		byte[] first = new byte[32 * 1024 + 12];
		byte[] second = first.clone();
		byte[] firstSuffix = HexFormat.of().parseHex("fe04317532928dbdad0403ba");
		byte[] secondSuffix = HexFormat.of().parseHex("2fbf30b89ab913221027aabb");
		System.arraycopy(firstSuffix, 0, first, first.length - firstSuffix.length, firstSuffix.length);
		System.arraycopy(secondSuffix, 0, second, second.length - secondSuffix.length, secondSuffix.length);
		CRC32 crc = new CRC32();
		crc.update(first);
		long firstHash = crc.getValue();
		crc.reset();
		crc.update(second);
		assertThat(crc.getValue()).as("Fixture values must share the candidate hash").isEqualTo(firstHash);
		assertThat(Arrays.equals(first, second)).isFalse();
		try (DataStore store = new DataStore(directory.toFile(), "collision", false)) {
			int firstId = store.storeData(first);
			int secondId = store.storeData(second);
			assertThat(secondId).isNotEqualTo(firstId);
			assertThat(store.getID(first)).isEqualTo(firstId);
			assertThat(store.getID(second)).isEqualTo(secondId);
			assertThat(store.storeData(second)).isEqualTo(secondId);
		}
	}

	@Test
	void preservesEmptyValueDeduplication() throws Exception {
		try (DataStore store = new DataStore(directory.toFile(), "empty", false)) {
			int id = store.storeData(new byte[0]);
			assertThat(store.getID(new byte[0])).isEqualTo(id);
			assertThat(store.storeData(new byte[0])).isEqualTo(id);
		}
	}

	@Test
	void preservesCompleteCandidateDebugSummariesAfterMismatches() throws Exception {
		byte[] data = new byte[32 * 1024 + 7];
		for (int i = 0; i < data.length; i++) {
			data[i] = (byte) (i * 31);
		}
		byte[] different = data.clone();
		different[0] ^= 1;
		String summary = "len=" + data.length + ",hash=" + Arrays.hashCode(data);
		try (DataFile file = new DataFile(directory.resolve("summary.dat").toFile())) {
			long offset = file.storeData(data);
			DataFile.RecordMatcher contentMismatch = file.matcher(different);
			assertThat(contentMismatch.matches(offset, true)).isFalse();
			assertThat(contentMismatch.summary()).isEqualTo(summary);
			DataFile.RecordMatcher lengthMismatch = file.matcher(new byte[0]);
			assertThat(lengthMismatch.matches(offset, true)).isFalse();
			assertThat(lengthMismatch.summary()).isEqualTo(summary);
		}
	}

	public static void main(String[] args) throws Exception {
		Path directory = Files.createDirectories(Path.of(args[0]));
		String lexical = "x".repeat(24 * 1024 * 1024);
		byte[] encoded = lexical.getBytes(StandardCharsets.UTF_8);
		try (DataStore store = new DataStore(directory.toFile(), "values", false)) {
			System.out.println("CANDIDATE_LOOKUP_START");
			if (store.getID(encoded) != 1) {
				throw new AssertionError("The existing value must retain its ID");
			}
			// Recovery retains the WAL lexical value while its encoded native bytes are deduplicated.
			Reference.reachabilityFence(lexical);
		}
		System.out.println("CANDIDATE_COMPARISON_PASSED");
	}
}
